tsInterfaces.ToolCategory:
{
  id: CategoryId;
  label: string;
  shortLabel: string;
  description: string;
  icon: "Braces" | "ShieldCheck" | "Workflow";
  color: string;
  glow: string;
  glowColor: string;
  gradientStart: string;
  gradientMid: string;
  gradientEnd: string;
  radialStartAngle: number;
  radialEndAngle: number;
  route: string;
}

tsInterfaces.Tool:
{
  /** Display name */
  name: string;
  /** URL-safe identifier */
  slug: string;
  /** Nested category-aware application path */
  route: string;
  /** Legacy flat path kept for compatibility */
  legacyRoute?: string;
  /** Short description */
  description: string;
  /** Display category label */
  category: string;
  /** Canonical category id */
  categoryId: CategoryId;
  /** Emoji icon displayed on the card */
  icon: string;
  /** Flag to indicate if the tool is an external link */
  isExternal?: boolean;
  /** External URL if isExternal is true */
  externalUrl?: string;
}
